            return FfiConverterTypeSession.lift(
    uniffiRustCallWithError(ChencangException) { _status ->
    UniffiLib.uniffi_chencang_bindings_fn_constructor_session_from_serialized_state(
    
        FfiConverterByteArray.lower(`state`),_status)
