sealed class ChencangException(message: String): kotlin.Exception(message) {
        
        class InvalidLength(message: String) : ChencangException(message)
        
        class UnsupportedSuite(message: String) : ChencangException(message)
        
        class UnsupportedVersion(message: String) : ChencangException(message)
        
        class AeadFailed(message: String) : ChencangException(message)
        
        class SignatureFailed(message: String) : ChencangException(message)
        
        class Decoding(message: String) : ChencangException(message)
        
        class Internal(message: String) : ChencangException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ChencangException> {
        override fun lift(error_buf: RustBuffer.ByValue): ChencangException = FfiConverterTypeChencangError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeChencangError : FfiConverterRustBuffer<ChencangException> {
    override fun read(buf: ByteBuffer): ChencangException {
        
            return when(buf.getInt()) {
            1 -> ChencangException.InvalidLength(FfiConverterString.read(buf))
            2 -> ChencangException.UnsupportedSuite(FfiConverterString.read(buf))
            3 -> ChencangException.UnsupportedVersion(FfiConverterString.read(buf))
            4 -> ChencangException.AeadFailed(FfiConverterString.read(buf))
            5 -> ChencangException.SignatureFailed(FfiConverterString.read(buf))
            6 -> ChencangException.Decoding(FfiConverterString.read(buf))
            7 -> ChencangException.Internal(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: ChencangException): ULong {
        return 4UL
    }

    override fun write(value: ChencangException, buf: ByteBuffer) {
        when(value) {
            is ChencangException.InvalidLength -> {
                buf.putInt(1)
                Unit
            }
            is ChencangException.UnsupportedSuite -> {
                buf.putInt(2)
                Unit
            }
            is ChencangException.UnsupportedVersion -> {
                buf.putInt(3)
                Unit
            }
            is ChencangException.AeadFailed -> {
                buf.putInt(4)
                Unit
            }
            is ChencangException.SignatureFailed -> {
                buf.putInt(5)
                Unit
            }
            is ChencangException.Decoding -> {
                buf.putInt(6)
                Unit
            }
            is ChencangException.Internal -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



sealed class DecodedMessage {
    
    data class Text(
        val `value`: kotlin.String) : DecodedMessage()
        
    {
        

        companion object
    }
    
    data class Media(
        val `refs`: List<uniffi.chencang.MediaRef>) : DecodedMessage()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDecodedMessage : FfiConverterRustBuffer<DecodedMessage>{
    override fun read(buf: ByteBuffer): DecodedMessage {
        return when(buf.getInt()) {
            1 -> DecodedMessage.Text(
                FfiConverterString.read(buf),
                )
            2 -> DecodedMessage.Media(
                FfiConverterSequenceTypeMediaRef.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DecodedMessage) = when(value) {
        is DecodedMessage.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`value`)
            )
        }
        is DecodedMessage.Media -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeMediaRef.allocationSize(value.`refs`)
            )
        }
    }

    override fun write(value: DecodedMessage, buf: ByteBuffer) {
        when(value) {
            is DecodedMessage.Text -> {
                buf.putInt(1)
                FfiConverterString.write(value.`value`, buf)
                Unit
            }
            is DecodedMessage.Media -> {
                buf.putInt(2)
                FfiConverterSequenceTypeMediaRef.write(value.`refs`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






